       return validateUserMessage(message);
     case 'ping':
       return validatePingMessage(message);
+    case 'list_sessions':
+      return validateListSessionsMessage(message);
     default:
       return {valid: false, error: `Unknown message type: ${message.type}`};
   }
@@ -72,3 +74,47 @@ function validatePingMessage(message: Record<string, unknown>): ValidationResult
     },
   };
 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const limit = parseLimit(message.limit);
+  if (limit === null) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+
+  const before = parseBeforeCursor(message.before);
+  if (before === null) {
+    return {valid: false, error: 'list_sessions before must carry a valid updatedAt and 1-128 char sessionId'};
+  }
+
+  const frame: ListSessionsMessage = {type: 'list_sessions'};
+  if (limit !== undefined) frame.limit = limit;
+  if (before !== undefined) frame.before = before;
+  return {valid: true, data: frame};
+}
+
+function parseLimit(rawLimit: unknown): number | undefined | null {
+  if (rawLimit === undefined) return undefined;
+  if (typeof rawLimit !== 'number') return null;
+  if (!Number.isInteger(rawLimit) || rawLimit < 0) return null;
+  return rawLimit;
+}
+
+const MAX_SESSION_ID_LENGTH = 128;
+
+function parseBeforeCursor(rawBefore: unknown): ListSessionsMessage['before'] | null {
+  if (rawBefore === undefined) return undefined;
+  if (typeof rawBefore !== 'object' || rawBefore === null) return null;
+  if (Array.isArray(rawBefore)) return null;
+
+  const candidate = rawBefore as Record<string, unknown>;
+  if (typeof candidate.sessionId !== 'string') return null;
+  if (candidate.sessionId.length < 1 || candidate.sessionId.length > MAX_SESSION_ID_LENGTH) return null;
+  if (!isTimestamp(candidate.updatedAt)) return null;
+
+  return {updatedAt: candidate.updatedAt, sessionId: candidate.sessionId};
+}
+
+function isTimestamp(rawUpdatedAt: unknown): rawUpdatedAt is string | number {
+  if (typeof rawUpdatedAt !== 'string' && typeof rawUpdatedAt !== 'number') return false;
+  return Number.isFinite(new Date(rawUpdatedAt).getTime());
+}
