describe('listing conversations', () => {
  const errors = captureErrors();

  it('answers list_sessions immediately for the session user with ISO dates, empty without listFor, and SERVER_ERROR on failure', async () => {
    const bareStore: SessionStore = {
      create: sessionId => ({sessionId, userId: 'u1', entries: []}),
      get: () => undefined,
      delete: () => false,
      count: () => 0,
      clear: () => undefined,
    };
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const store: SessionStore = {
      ...bareStore,
      listFor: (userId, options) => {
        seen.push({userId, options});
        return [
          {
            sessionId: 's2',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
            entryCount: 4,
          },
        ];
      },
    };
    const inFlight = gated(1, store);
    const run = inFlight.send(userMessage('A'));
    await afterPendingWork();
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    await inFlight.send({type: 'list_sessions', limit: 10, before, userId: 'u2'});
    const {sent} = inFlight;
    const whileStreaming = sent.at(-1);
    inFlight.release(0);
    await run;

    const omitted = gated(0);
    await omitted.send({type: 'list_sessions'});
    const unimplemented = gated(0, bareStore);
    await unimplemented.send({type: 'list_sessions'});
    const failing = gated(0, {...bareStore, listFor: () => Promise.reject(new Error('database offline'))});
    await failing.send({type: 'list_sessions'});
    const stringFailing = gated(0, {...bareStore, listFor: () => Promise.reject('raw failure')});
    await stringFailing.send({type: 'list_sessions'});

    expect({
      seen,
      whileStreaming,
      omitted: omitted.sent,
      unimplemented: unimplemented.sent,
      failing: failing.frames(),
      stringFailing: stringFailing.frames(),
      errors,
    }).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      whileStreaming: {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's2',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T00:02:00.000Z',
            entryCount: 4,
